import {
  ageLabel,
  ageLevel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

/**
 * Tabla de resultados de SRCH-01 · diez columnas, selección múltiple y
 * ordenación por cabecera.
 *
 * Componente presentacional puro: pinta las filas EN EL ORDEN QUE LAS RECIBE
 * (ordenar es de la pantalla) y no carga datos. El estado vacío vive aquí,
 * dentro de la tabla, en su propia fila con `<td colSpan>` — en una `<table>`
 * semántica es ahí donde corresponde (lección MSG-01).
 *
 * `onToggleFavorite` y `onContact` avisan con el id de la ORGANIZACIÓN;
 * `onToggleRow` y `onConsult`, con el de la LINEA.
 */

interface RowWithKey extends SearchResultRow {
  [key: string]: unknown;
}

const SORT_COLUMNS: SortColumn[] = ['brand', 'quantity', 'leadTime', 'country', 'age', 'favorites'];

const SORT_LABELS: Record<SortColumn, string> = {
  brand: 'Marca',
  quantity: 'Cantidad',
  leadTime: 'Plazo',
  country: 'País',
  age: 'Antigüedad',
  favorites: 'Favoritos',
};

interface Props {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}

export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: Props) {
  const allSelected = rows.length > 0 && rows.every((r) => selected.has(r.id));
  const someSelected = selected.size > 0 && !allSelected;

  return (
    <div className={styles.outer}>
      <table className={styles.table}>
        <thead>
          <tr>
            <th className={styles.thChk}>
              <input
                type="checkbox"
                className={styles.rowCheck}
                aria-label="Seleccionar todas las filas"
                checked={allSelected}
                ref={(el) => {
                  if (el) el.indeterminate = someSelected;
                }}
                onChange={() => {
                  /* Sin callback específico de selección total en el contrato:
                     se emite por línea, como el resto de la selección. */
                  rows.forEach((r) => onToggleRow(r.id));
                }}
              />
            </th>
            <th>Referencia</th>

            {SORT_COLUMNS.map((col) => {
              const active = sort?.column === col;
              const direction = active ? sort?.direction : null;
              return (
                <th
                  key={col}
                  aria-sort={
                    active
                      ? direction === 'asc'
                        ? 'ascending'
                        : 'descending'
                      : 'none'
                  }
                  className={
                    active
                      ? direction === 'asc'
                        ? `${styles.sortable} ${styles.sortAsc}`
                        : `${styles.sortable} ${styles.sortDesc}`
                      : styles.sortable
                  }
                >
                  <button
                    type="button"
                    className={styles.sortBtn}
                    onClick={() => onSort(col)}
                  >
                    {SORT_LABELS[col]}
                  </button>
                </th>
              );
            })}

            <th>Empresa</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={10} className={styles.emptyCell}>
                No hemos encontrado stock con estos filtros.
              </td>
            </tr>
          ) : (
            rows.map((row) => {
              const r = row as RowWithKey;
              const level = ageLevel(daysSince(row.lastUploadAt, now));
              const days = daysSince(row.lastUploadAt, now);
              const stale = days > 7;
              const qtyOk = meetsMinQuantity(row.quantity, minQuantity);

              return (
                <tr
                  key={row.id}
                  className={row.consulted ? styles.consultedRow : undefined}
                >
                  <td className={styles.tdChk}>
                    <input
                      type="checkbox"
                      className={styles.rowCheck}
                      aria-label={`Seleccionar ${row.partNumber} de ${row.orgName}`}
                      checked={selected.has(row.id)}
                      onChange={() => onToggleRow(row.id)}
                    />
                  </td>
                  <td>
                    <span className={styles.cellRef}>{row.partNumber}</span>
                  </td>
                  <td>
                    <span className={styles.badgeMarca}>{row.brand}</span>
                  </td>
                  <td>
                    <span className={qtyOk ? styles.cellQtyOk : styles.cellQtyLow}>
                      {quantityLabel(row.quantity)}
                    </span>
                  </td>
                  <td>
                    <span className={styles.cellPlazo}>
                      {leadTimeLabel(row.leadTimeDays)}
                    </span>
                  </td>
                  <td>
                    <span className={styles.cellEmpresa}>{row.orgName}</span>
                  </td>
                  <td>
                    <span className={styles.badgePais}>{countryName(row.country)}</span>
                  </td>
                  <td>
                    <span className={stale ? `${styles.cellAntiguedad} ${styles.stale}` : styles.cellAntiguedad}>
                      {ageLabel(days, level)}
                    </span>
                  </td>
                  <td>
                    <button
                      type="button"
                      className={styles.cellFav}
                      aria-pressed={row.isFavorite}
                      aria-label={`${row.isFavorite ? 'Quitar' : 'Marcar'} favorita a ${row.orgName} (${row.favoriteCount} favoritos)`}
                      onClick={() => onToggleFavorite(row.orgId)}
                    >
                      <span className={styles.favStar} aria-hidden="true">
                        {row.isFavorite ? '★' : '☆'}
                      </span>
                      <span className={styles.favCount}>{row.favoriteCount}</span>
                    </button>
                  </td>
                  <td>
                    <div className={styles.actionsCell}>
                      <button
                        type="button"
                        className={styles.btnConsultar}
                        disabled={row.consulted}
                        title={row.consulted ? 'Ya consultada anteriormente' : undefined}
                        aria-label={`Consultar ${row.partNumber}`}
                        onClick={() => onConsult(row.id)}
                      >
                        Consultar
                      </button>
                      <button
                        type="button"
                        className={styles.btnContactar}
                        aria-label={`Contactar ${row.orgName}`}
                        onClick={() => onContact(row.orgId)}
                      >
                        Contactar
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

