import { useCallback, useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchResults,
  metaCounterLabel,
  sortRows,
  type SearchCriteria,
  type Sort,
} from '../../lib/search';
import { EMPTY_CRITERIA } from '../../lib/search';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

/**
 * SRCH-01 · Panel de Resultados de Búsqueda.
 *
 * La pantalla, no un componente de presentación: posee criterios, orden,
 * selección, carga y error, consulta `fetchResults` y ordena con `sortRows`
 * antes de pasar las filas a la tabla.
 *
 * `now` es inyectable para que los tests no dependan del reloj.
 */

interface Props {
  profile: MemberProfile;
  now?: Date;
}

export function SearchResults({ profile, now }: Props) {
  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [rows, setRows] = useState<Awaited<ReturnType<typeof fetchResults>>['rows']>([]);
  const [total, setTotal] = useState(0);
  const [capped, setCapped] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [retryTick, setRetryTick] = useState(0);

  /* Sin dependencia de librería de utilidades: `sanitizeSearch` no se
     reimplementa, se deja trabajar a `fetchResults`. */
  const nowRef = now ?? new Date();

  useEffect(() => {
    let cancelled = false;

    setLoading(true);
    setError(null);

    fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria })
      .then((page) => {
        if (cancelled) return;
        setRows(page.rows);
        setTotal(page.total);
        setCapped(page.capped);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e instanceof Error ? e.message : 'No se pudieron cargar los resultados.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, profile.id, criteria, retryTick]);

  /* Resultados nuevos → selección de la página anterior es basura. */
  useEffect(() => {
    setSelected(new Set());
  }, [criteria]);

  const toggleRow = useCallback((lineId: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(lineId)) {
        next.delete(lineId);
      } else {
        next.add(lineId);
      }
      return next;
    });
  }, []);

  const toggleAll = useCallback(() => {
    setSelected((prev) => {
      const allSelected = rows.length > 0 && rows.every((r) => prev.has(r.id));
      if (allSelected) return new Set();
      return new Set(rows.map((r) => r.id));
    });
  }, [rows]);

  const ordered = sortRows(rows, sort);
  const selectedCount = selected.size;
  const consultDisabled = selectedCount < 2 || loading;

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</p>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <div
        className={styles.resultsArea}
        aria-busy={loading ? 'true' : 'false'}
        aria-live="polite"
      >
        <FilterChips criteria={criteria} onChange={setCriteria} />

        <div className={styles.metabar}>
          <p className={styles.metaCount}>
            <strong>{metaCounterLabel(total, rows.filter((r) => (criteria.minQuantity === null || r.quantity >= criteria.minQuantity)).length, criteria.minQuantity)}</strong>
          </p>
          <button
            type="button"
            className={styles.selAll}
            onClick={toggleAll}
            disabled={rows.length === 0}
          >
            {rows.length > 0 && rows.every((r) => selected.has(r.id))
              ? 'Deseleccionar todos'
              : 'Seleccionar todos'}
          </button>
          <button
            type="button"
            className={styles.consultSel}
            onClick={() => {
              /* Contrato de la capability `conversational-search · results-row-actions`:
                 el lote se habilita con DOS o más filas marcadas. El destino real de la
                 consulta es la fila del día 10 del Plan §3 (GAP-004); hoy el botón solo
                 existe — no se simula ningún envío. */
            }}
            disabled={consultDisabled}
          >
            Consultar seleccionados
          </button>
          <button
            type="button"
            className={styles.watcherBtn}
            disabled
            title="Crear watcher está fuera del alcance del MVP (SRCH-03, Plan §9)"
          >
            <i className="ti ti-bell-plus" aria-hidden="true" />
            Crear watcher con estos criterios
          </button>
        </div>

        {capped && (
          <p className={styles.capped}>
            Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
          </p>
        )}

        {error ? (
          <div className={styles.errorBox} role="alert">
            <p>{error}</p>
            <button
              type="button"
              className={styles.retryBtn}
              onClick={() => setRetryTick((t) => t + 1)}
            >
              Reintentar
            </button>
          </div>
        ) : (
          <div className={styles.tableArea}>
            {loading && (
              <div className={styles.spinner} role="status" aria-label="Buscando resultados">
                <span aria-hidden="true" />
              </div>
            )}
            <ResultsTable
              rows={ordered}
              sort={sort}
              selected={selected}
              minQuantity={criteria.minQuantity}
              now={nowRef}
              onSort={setSort}
              onToggleRow={toggleRow}
              onToggleFavorite={() => {}}
              onConsult={() => {}}
              onContact={() => {}}
            />
          </div>
        )}
      </div>
    </div>
  );
}
